"""The QL classes over the generated tables: one per node type with a getter per field, and one per union."""

from collections.abc import Mapping
from functools import singledispatch

from cobble.experimental.codeql.schema.dbscheme import (
    AST_NODE,
    child_table,
    is_column,
    present,
)
from cobble.experimental.codeql.schema.schema import NodeField, NodeType, Schema
from cobble.experimental.codeql.schema.shape import (
    Absent,
    Keyed,
    Located,
    NodeRef,
    Repeated,
    Scalar,
    Shape,
)

HEADER = (
    "/**\n"
    " * Generated by cobble-experimental-codeql-schema from the parser's types: "
    "do not edit.\n"
    " */\n\n"
    "private import cobol.Locations as L\n\n"
)


def _pascal(name: str) -> str:
    return "".join(part.capitalize() for part in name.split("_"))


Classes = Mapping[str, str]


def _classes(schema: Schema) -> Classes:
    """The QL class of each dbscheme type."""
    return {
        **{n.table: n.name for n in schema.nodes},
        **{u.table: u.name for u in schema.unions},
    }


@singledispatch
def _type(shape: Shape, classes: Classes) -> str:
    raise TypeError(f"{shape} has no QL type")


@_type.register
def _(shape: Scalar, classes: Classes) -> str:
    return shape.kind.value


@_type.register
def _(shape: NodeRef, classes: Classes) -> str:
    return classes[shape.name]


@_type.register
def _(shape: Located, classes: Classes) -> str:
    return "L::Location"


def _direct(node: NodeType, field: NodeField, classes: Classes) -> str:
    columns = tuple(f for f in node.fields if is_column(f.shape))
    args = ", ".join("result" if f is field else "_" for f in columns)
    return _getter(
        _type(field.shape, classes), field, "", f"{node.table}_def(this, {args})"
    )


def _getter(result: str, field: NodeField, parameters: str, body: str) -> str:
    name = f"get{_pascal(field.name)}"
    return f"    {result} {name}({parameters}) {{ {body} }}\n"


def _accessors(node: NodeType, field: NodeField, classes: Classes) -> str:
    return _getters(field.shape, node, field, classes)


@singledispatch
def _getters(shape: Shape, node: NodeType, field: NodeField, classes: Classes) -> str:
    """A column on the owner's row is read from its ``_def`` table."""
    return _direct(node, field, classes)


@_getters.register
def _(shape: Absent, node: NodeType, field: NodeField, classes: Classes) -> str:
    table = child_table(node, field)
    return _getter(_type(shape.inner, classes), field, "", f"{table}(this, result)")


@_getters.register
def _(shape: Repeated, node: NodeType, field: NodeField, classes: Classes) -> str:
    table = child_table(node, field)
    body = f"{table}(this, i, result)"
    return _getter(_type(shape.element, classes), field, "int i", body)


@_getters.register
def _(shape: Keyed, node: NodeType, field: NodeField, classes: Classes) -> str:
    return _keyed(field, child_table(node, field), shape.value, classes)


def _keyed(field: NodeField, table: str, value: Shape, classes: Classes) -> str:
    key = NodeField(f"{field.name}_key", value, 0)
    return _getter("string", key, "int i", f"{table}(this, i, result)") + _getter(
        _type(present(value), classes),
        field,
        "int i",
        f"{table}_value(this, i, result)",
    )


def _node_class(node: NodeType, classes: Classes) -> str:
    getters = "".join(_accessors(node, f, classes) for f in node.fields)
    return (
        f"  class {node.name} extends AstNode, @{node.table} {{\n"
        f'    override string getAPrimaryQlClass() {{ result = "{node.name}" }}\n'
        f"{getters}"
        "  }\n"
    )


def _located(node: NodeType) -> tuple[str, ...]:
    """How a node of this type finds its place: through each field that holds a
    ``SourceSpan``."""
    return tuple(
        f"result = this.({node.name}).get{_pascal(f.name)}()"
        for f in node.fields
        if f.shape in (Located(), Absent(Located()))
    )


def _location(schema: Schema) -> str:
    found = tuple(d for n in schema.nodes for d in _located(n))
    body = "\n      or\n      ".join(found) if found else "none()"
    return f"    L::Location getLocation() {{\n      {body}\n    }}\n"


def ql_text(schema: Schema) -> str:
    classes = _classes(schema)
    unions = "".join(
        f"  class {u.name} extends AstNode, @{u.table} {{ }}\n" for u in schema.unions
    )
    return (
        HEADER
        + "module Generated {\n"
        + f"  class AstNode extends @{AST_NODE} {{\n"
        + "    string toString() { result = this.getAPrimaryQlClass() }\n\n"
        + "    string getAPrimaryQlClass() { none() }\n\n"
        + _location(schema)
        + "  }\n\n"
        + "\n".join(_node_class(n, classes) for n in schema.nodes)
        + "\n"
        + unions
        + "}\n"
    )
